import type { Alignment, Element, Stats, Trajectory, UnitKind } from '../types';

// The thirty Summoners, generated by the Stat Budget generator
// (rules/statgen.ts, scripts/summoners.run.ts) and kept here as fixed data.
// Every Side picks one before the match. All walk + wade and cast Bolt, Rise
// and Ebb; five attack at range, four have an Element and four an
// Alignment. Each spread sums to the Stat Budget: MP, which also sets Mana
// Income, trades against Speed, Move, the defences and (at range) ATK.
// The comment after each is its distance from the budget in MP.

type Def = [
  id: string,
  name: string,
  stats: [atk: number, def: number, mp: number, mdf: number, spd: number, mov: number],
  range: number,
  trajectory?: Trajectory,
  element?: Element | null,
  alignment?: Alignment,
];

const DEFS: Def[] = [
  ['corsair', 'Corsair', [11, 9, 13, 11, 10, 5], 3, 'direct'], // +0.21
  ['lancer', 'Lancer', [15, 12, 9, 15, 15, 4], 4, 'direct'], // -0.04
  ['harpist', 'Harpist', [11, 11, 13, 10, 10, 3], 4, 'direct'], // -0.29
  ['savage', 'Savage', [14, 15, 8, 13, 14, 6], 5, 'high'], // -0.11
  ['tracker', 'Tracker', [8, 9, 11, 10, 14, 4], 6, 'high'], // +0.07
  ['witch', 'Witch', [4, 6, 15, 5, 10, 4], 1], // -0.18
  ['sylph', 'Sylph', [3, 4, 13, 6, 14, 5], 1, undefined, 'air'], // +0.17
  ['duelist', 'Duelist', [4, 4, 14, 5, 14, 3], 1], // +0.11
  ['valkyr', 'Valkyr', [17, 13, 11, 8, 13, 5], 1], // -0.28
  ['lich', 'Lich', [3, 6, 15, 12, 10, 3], 1], // +0.15
  ['seraph', 'Seraph', [10, 10, 12, 15, 13, 3], 1, undefined, null, 'day'], // -0.09
  ['regent', 'Regent', [11, 9, 11, 12, 13, 6], 1], // -0.12
  ['warlock', 'Warlock', [10, 4, 14, 9, 12, 4], 1], // +0.22
  ['satyr', 'Satyr', [10, 7, 10, 9, 17, 5], 1], // -0.23
  ['efreet', 'Efreet', [12, 10, 12, 5, 15, 4], 1, undefined, 'fire'], // +0.29
  ['templar', 'Templar', [15, 14, 12, 12, 12, 4], 1, undefined, null, 'day'], // +0.29
  ['banshee', 'Banshee', [4, 5, 13, 12, 14, 3], 1, undefined, null, 'night'], // +0.11
  ['ronin', 'Ronin', [15, 10, 11, 9, 16, 3], 1], // -0.09
  ['oni', 'Oni', [18, 14, 9, 10, 17, 4], 1], // -0.25
  ['vampire', 'Vampire', [10, 10, 13, 6, 12, 5], 1, undefined, null, 'night'], // +0.28
  ['herald', 'Herald', [14, 11, 10, 12, 15, 5], 1], // -0.16
  ['oracle', 'Oracle', [2, 5, 13, 11, 12, 5], 1], // -0.15
  ['gorgon', 'Gorgon', [12, 12, 11, 15, 12, 5], 1], // -0.27
  ['naga', 'Naga', [7, 9, 14, 7, 12, 3], 1], // +0.18
  ['magus', 'Magus', [4, 3, 15, 8, 11, 3], 1], // -0.25
  ['shadow', 'Shadow', [7, 5, 12, 8, 16, 3], 1], // -0.24
  ['selkie', 'Selkie', [5, 6, 11, 12, 15, 5], 1, undefined, 'water'], // -0.22
  ['lamia', 'Lamia', [10, 7, 13, 13, 12, 4], 1], // +0.17
  ['hermit', 'Hermit', [5, 9, 14, 9, 10, 4], 1], // -0.20
  ['dwarf', 'Dwarf', [17, 12, 12, 9, 13, 3], 1, undefined, 'earth'], // -0.28
];

function build([id, name, s, range, trajectory, element, alignment]: Def): UnitKind {
  const stats: Stats = { atk: s[0], def: s[1], mp: s[2], mdf: s[3], spd: s[4], mov: s[5] };
  return {
    id,
    name,
    isSummoner: true,
    element: element ?? null,
    alignment: alignment ?? 'none',
    cost: 0,
    role: 'summoner',
    stats,
    moveTypes: ['walk', 'wade'],
    attack: range > 1 ? { range, trajectory: trajectory ?? 'direct' } : { range: 1 },
    magic: [
      { id: 'bolt', name: 'Bolt', kind: 'damage', range: 3, radius: 0, manaCost: 24, trajectory: 'direct' },
      { id: 'rise', name: 'Rise', kind: 'water', delta: 1, manaCost: 32 },
      { id: 'ebb', name: 'Ebb', kind: 'water', delta: -1, manaCost: 32 },
    ],
  };
}

/** Built-in Summoners (before any balance overrides). */
export const BASE_SUMMONERS: readonly UnitKind[] = DEFS.map(build);

/** The default Summoner (Regent, an all-rounder). */
export const DEFAULT_SUMMONER = 'regent';
